-- Migration 0017: CFO Policy Provenance Forward Correction & Reconciliation Freshness Columns
-- Forward corrections preserving existing applied migrations and isolating synthetic fixtures

-- 1. Forward correction for POL-004:
-- POL-004 was generated by migration, not approved by Finverse.
-- Treat its zero-tolerance/24-hour values as illustrative until confirmed.
-- Do not manufacture approval identities [Deck P320 Category 3].
UPDATE finance_policies
SET
  is_demo_policy = true,
  status = 'draft',
  approved_by_employee_id = NULL,
  rules_summary = 'Illustrative period close & materiality governance policy [Illustrative demo assumption; Zero-tolerance threshold and 24h freeze window are unconfirmed client decisions Deck P320 Category 3, not an approved production mandate].',
  approval_limits = '{"materiality_threshold": 0.00, "require_all_active_verticals": true, "max_reconciliation_age_hours": 24, "is_illustrative": true, "client_approved": false}'
WHERE id = 'POL-004';

-- 2. Add updated_at to finance_ledger_entries if not already present
ALTER TABLE finance_ledger_entries
ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW();

-- 3. Trigger or default to keep updated_at in sync on ledger entry updates
CREATE OR REPLACE FUNCTION update_finance_ledger_entries_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_finance_ledger_entries_updated_at ON finance_ledger_entries;
CREATE TRIGGER trg_finance_ledger_entries_updated_at
BEFORE UPDATE ON finance_ledger_entries
FOR EACH ROW
EXECUTE FUNCTION update_finance_ledger_entries_updated_at();
